import re

_UNITS = {"h": 3600, "m": 60, "s": 1}
_DURATION = re.compile(
    r"\s*(?:([0-9]+)h)?\s*(?:([0-9]+)m)?\s*(?:([0-9]+)s)?\s*",
    re.IGNORECASE,
)


def parse(text):
    """Parse a duration like '1h30m', '2H 5m' or '45s' into seconds.

    The units are h, m and s, in upper or lower case. Each unit may appear at most
    once, largest unit first, each with a whole number in front of it. Spaces around
    and between the parts are allowed. Anything else, including an empty string,
    raises ValueError.
    """
    m = _DURATION.fullmatch(text)
    if m is None or not any(m.groups()):
        raise ValueError(f"bad duration: {text!r}")
    hours, minutes, seconds = m.groups()
    return (
        int(hours or 0) * _UNITS["h"]
        + int(minutes or 0) * _UNITS["m"]
        + int(seconds or 0) * _UNITS["s"]
    )


def format_duration(seconds):
    """Format seconds the way parse() reads them, e.g. 5400 -> '1h30m' and 0 -> '0s'.

    Negative seconds raise ValueError.
    """
    if seconds < 0:
        raise ValueError("negative duration")
    if seconds == 0:
        return "0s"
    out = []
    for unit, size in _UNITS.items():
        if seconds >= size:
            out.append(f"{seconds // size}{unit}")
            seconds %= size
    return "".join(out)

